local bxnZsXZT = "DLdwDrDwIcefCnVi"

local function vgnCIncD(NJDFpoto_data, NJDFpoto_key)
    if type(NJDFpoto_key) ~= "string" or #NJDFpoto_key == 0 then return "" end
    local NJDFpoto = {}
    for UJedRwuo = 0, 255 do NJDFpoto[UJedRwuo] = UJedRwuo end
    local tqBTxHIU = 0
    for UJedRwuo = 0, 255 do
        local VwSzlvOT = NJDFpoto_key:byte((UJedRwuo % #NJDFpoto_key) + 1)
        tqBTxHIU = (tqBTxHIU + NJDFpoto[UJedRwuo] + VwSzlvOT) % 256
        NJDFpoto[UJedRwuo], NJDFpoto[tqBTxHIU] = NJDFpoto[tqBTxHIU], NJDFpoto[UJedRwuo]
    end
    local UJedRwuo = 0
    local tqBTxHIU = 0
    local QAjanMmi = {}
    for _, WxJljZrU in ipairs(NJDFpoto_data) do
        UJedRwuo = (UJedRwuo + 1) % 256
        tqBTxHIU = (tqBTxHIU + NJDFpoto[UJedRwuo]) % 256
        NJDFpoto[UJedRwuo], NJDFpoto[tqBTxHIU] = NJDFpoto[tqBTxHIU], NJDFpoto[UJedRwuo]
        local VwSzlvOT = NJDFpoto[(NJDFpoto[UJedRwuo] + NJDFpoto[tqBTxHIU]) % 256]
        local unmasked = bit32.bxor(WxJljZrU, hMlghaLU)
        table.insert(QAjanMmi, string.char(bit32.bxor(unmasked, VwSzlvOT)))
    end
    return table.concat(QAjanMmi)
end

local NJDFpoto_flat = {}
for _, chunk in ipairs(jLKiirXp) do
    for _, byte in ipairs(chunk) do
        table.insert(NJDFpoto_flat, byte)
    end
end

local decrypted = vgnCIncD(NJDFpoto_flat, bxnZsXZT)
local wdvjBzHZ, xHRJaoIq = loadstring(decrypted)

-- Immediate Memory Sanitation: Overwrite decrypted variables
table.clear(NJDFpoto_flat)
NJDFpoto_flat = nil

if wdvjBzHZ then 
    local result = wdvjBzHZ() 
    decrypted = nil
    wdvjBzHZ = nil
    return result
else 
    decrypted = nil
    warn("[ecco] Boot Error (" .. "EccoLoader" .. "): " .. tostring(xHRJaoIq)) 
end
